-- Publish approved snapshots; never overwrite personal recipes or recorded history.
alter table public.meals drop constraint meals_image_shape;
alter table public.meals add constraint meals_image_shape check (image is null or (jsonb_typeof(image)='object' and ((image->>'kind'='asset' and image->>'id' in ('creamy-lemon-chicken','korean-beef-bowl','breakfast-egg-salad','snack-sandwich','dinner-curry-omelette','sticky-teriyaki-chicken','chicken-burrito-protein-boxes','hainanese-chicken-rice','korean-broccoli-side-dish','tortang-talong-with-chicken')) or (image->>'kind'='url' and jsonb_typeof(image->'url')='string' and char_length(image->>'url')<=2048 and image->>'url' ~ '^https://[^/@[:space:]]+([/?#]|$)') or (image->>'kind'='upload' and jsonb_typeof(image->'path')='string' and image->>'path' ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$'))) is true);
do $migration$
declare definition text;
begin
 select pg_get_functiondef('private.save_saved_meal_without_complexity(jsonb)'::regprocedure) into definition;
 if position('''creamy-lemon-chicken'',''korean-beef-bowl'',''breakfast-egg-salad'',''snack-sandwich'',''dinner-curry-omelette'',''sticky-teriyaki-chicken'',''chicken-burrito-protein-boxes''' in definition)=0 then raise exception 'Unexpected recipe image validation baseline'; end if;
 execute replace(definition,'''creamy-lemon-chicken'',''korean-beef-bowl'',''breakfast-egg-salad'',''snack-sandwich'',''dinner-curry-omelette'',''sticky-teriyaki-chicken'',''chicken-burrito-protein-boxes''','''creamy-lemon-chicken'',''korean-beef-bowl'',''breakfast-egg-salad'',''snack-sandwich'',''dinner-curry-omelette'',''sticky-teriyaki-chicken'',''chicken-burrito-protein-boxes'',''hainanese-chicken-rice'',''korean-broccoli-side-dish'',''tortang-talong-with-chicken''');
end;
$migration$;
revoke all on function private.save_saved_meal_without_complexity(jsonb) from public,anon,authenticated;
grant execute on function private.save_saved_meal_without_complexity(jsonb) to postgres;
-- Apply the requested zero-calorie correction only to the source Hainanese recipe.
update public.meal_ingredients i set food_row_id=(select row_id from public.foods where app_id='food-default-water-zero') from public.meals m,public.foods f where i.meal_row_id=m.row_id and i.food_row_id=f.row_id and m.app_id='meal-f86a5f62-a744-4213-8460-e0e363754ef1' and not m.is_system and f.app_id='food-fdc-2047057';
update public.meals set updated_at=now() where app_id='meal-f86a5f62-a744-4213-8460-e0e363754ef1' and not is_system;
notify pgrst,'reload schema';
